from threetears.evals import Eval

from score import Message, load_contacts, score

CONTACTS = load_contacts("data/contacts.txt")


def rate(case):
    """The spam score the filter gives the message."""
    return {"score": score(Message.from_row(case), CONTACTS)}


def agrees_with_moderators(case, out):
    """The score is within 1.5 of the moderators' mean, as the README counts agreement."""
    return abs(out["score"] - case["panel"]) <= 1.5 + 1e-9

messages = Eval("data/rated.jsonl", runner=rate, grader=[agrees_with_moderators], k=1)
